<!--
  Ficheiro: src/components/live/ChannelDetailDialog.vue
  Tipo: Diálogo Vue.
  Função: Mostra detalhes, relações IPTV/XMLTV e fontes do canal.
-->
<script setup lang="ts">
import { nextTick,ref,watch } from "vue";import { pb } from "@/infrastructure/pocketbase/client";import type { ChannelRecord,StreamLinkRecord } from "@/types/records";import StreamLinkList from "./StreamLinkList.vue";import { qualityLabel } from "@/domain/live/format";
const props=defineProps<{channel:ChannelRecord|null;links:StreamLinkRecord[];loading:boolean}>();const emit=defineEmits<{close:[];edit:[ChannelRecord]}>();const closeButton=ref<HTMLButtonElement|null>(null);watch(()=>props.channel,async v=>{if(v){await nextTick();closeButton.value?.focus()}});function logo(c:ChannelRecord){return c.logo?pb.files.getURL(c,c.logo,{thumb:"256x256"}):c.tvg_logo_url||""}
</script>
<template><Teleport to="body"><div v-if="channel" class="dialog-backdrop" @click.self="emit('close')"><section class="dialog-panel channel-detail" role="dialog" aria-modal="true" aria-labelledby="channel-detail-title" @keydown.esc="emit('close')"><button ref="closeButton" class="icon-button channel-detail-close" type="button" aria-label="Fechar detalhe" @click="emit('close')">×</button><header class="channel-detail-header"><div class="channel-detail-logo"><img v-if="logo(channel)" :src="logo(channel)" :alt="`Logótipo de ${channel.nome}`"/><span v-else aria-hidden="true">▣</span></div><div><p class="eyebrow">{{channel.expand?.categoria?.nome||"Canal TV"}}</p><h2 id="channel-detail-title">{{channel.nome}}</h2><p>{{qualityLabel(channel.qualidade)}} · {{channel.expand?.pais?.nome||"País desconhecido"}} · {{channel.ativo===false?"Inativo":"Ativo"}}</p><button class="button button-primary" type="button" @click="emit('edit',channel)">Editar canal</button></div></header><section class="detail-section"><h3>Fontes disponíveis</h3><div v-if="loading" class="page-loading"><span class="loader"/></div><StreamLinkList v-else :channel="channel" :links="links"/></section><details class="detail-section"><summary>Dados técnicos IPTV/XMLTV</summary><dl class="channel-tech"><div><dt>TVG-ID</dt><dd>{{channel.tvg_id||"—"}}</dd></div><div><dt>TVG name</dt><dd>{{channel.tvg_name||"—"}}</dd></div><div><dt>EPG-ID</dt><dd>{{channel.epg_id||"—"}}</dd></div><div><dt>Playlist</dt><dd>{{channel.playlist_origem||"—"}}</dd></div></dl></details></section></div></Teleport></template>
